// 1 o 2 bloques GUID (8-4-4-4-12): el `id` de /v2/tokeninfo es la mitad (36 + 1 + 36 = 73).
function isValidKeyFormat(v) {
  return /^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}(?:-[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12})*$/.test(v);
}

ops.text:
// BL-079 (2026-10-28): la API Key real de GW2 tiene 72 caracteres, 8-4-4-4-20-4-4-4-12: dos GUID pegados SIN guion
// entre medio (el segundo empieza dentro del bloque de 20). La regla vieja pedía un guion ahí y rechazaba toda Key nueva.
var KEY_FORMAT = /^[0-9A-Fa-f]{8}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{20}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{4}-[0-9A-Fa-f]{12}$/;
function isValidKeyFormat(v) {
  return KEY_FORMAT.test(v);
}
